// Create client
const connectionString = "<Your App Configuration Connection String>";
const client = new AppConfigurationClient(connectionString);

// This structure is taken from Microsoft's feature management schema
const betaFeatureFlag = {
  id: "BetaFeature",
  enabled: true,
  conditions: {
    client_filters: []
  }
};

await client.setConfigurationSetting({
  key: `.appconfig.featureflag/BetaFeature`,
  value: JSON.stringify(betaFeatureFlag),
  contentType: "application/vnd.microsoft.appconfig.ff+json;charset=utf-8"
});

// Retrieve and check if it's a valid feature flag
const setting = await client.getConfigurationSetting({ key: `.appconfig.featureflag/BetaFeature` });
if (isFeatureFlag(setting)) {
  console.log("Feature flag retrieved:", setting);
}
